```
class ChartCreator {
    constructor(dataUrl) {
        this.dataUrl = dataUrl;
        this.chartData = null;
    }

    async init() {
        await this.fetchData();
        if (this.chartData) {
            this.createCharts();
        }
    }

    async fetchData() {
        try {
            const response = await fetch(this.dataUrl);
            if (!response.ok) {
                throw new Error('Network response was not ok ' + response.statusText);
            }
            this.chartData = await response.json();
        } catch (error) {
            console.error('There has been a problem with your fetch operation:', error);
        }
    }

    createCharts() {
        // This method will be overridden in subclasses
        throw new Error('createCharts() must be implemented in subclasses');
    }
}

class LineChart extends ChartCreator {
    constructor(dataUrl) {
        super(dataUrl);
        this.areaCtx = document.getElementById('areaChart');
    }   

    createCharts() {
        this.createAreaChart();
    }

    createAreaChart() {
        new Chart(this.areaCtx, {
            type: 'line',
            data: {
                labels: this.chartData.labels,
                datasets: [{
                    label: '# of Debts',
                    data: this.chartData.data,
                    borderColor: 'rgba(0, 0, 0, 1)', 
                    backgroundColor: 'rgba(50, 50, 50, 1)', 
                    
                    fill: true,
                    borderWidth: 2
                }]
            },
            options: {
                scales: {
                    y: {
                        beginAtZero: true
                    }
                }
            }
        });
    }
}

class BarChart extends ChartCreator {
    constructor(dataUrl) {
        super(dataUrl);
        this.barCtx = document.getElementById('barChart');
    }

    createCharts() {
        this.createBarChart();
    }

    createBarChart() {
        new Chart(this.barCtx, {
            type: 'bar',
            data: {
                labels: this.chartData.labels,
                datasets: [{
                    label: '# of people agreed',
                    borderColor: 'rgba(0, 0, 0, 1)', // Opaque black for border
                    backgroundColor: 'rgba(50, 50, 50, 1)', // Lighter shade of black (dark gray)
                    data: this.chartData.data,
                    borderWidth: 5
                }]
            },
            options: {
                scales: {
                    y: {
                        beginAtZero: true
                    }
                }
            }
        });
    }
}

const lineChartCreator = new LineChart('data.json');
lineChartCreator.init();

const barChartCreator = new BarChart('data.json');
barChartCreator.init();

console.log(lineChartCreator.dataUrl);
console.log(barChartCreator.dataUrl);
```
**Conclusion**
This implementation allows for easy creation of different chart types by leveraging object-oriented programming principles. The ChartCreator class serves as a reusable base for fetching data and setting up the initial chart structure. Subclasses like LineChart and BarChart provide specific functionality, making the solution extensible. With the use of Chart.js, the visualization process becomes straightforward and customizable. This design also allows users to easily modify the chart types or switch data sources by changing the URL. By separating data fetching and chart creation, the code remains clean, organized, and adaptable to future charting needs.

